      />

      <FormField
        id="email"
        label="Email address"
        type="email"
        required
        autoComplete="email"
        inputMode="email"
        value={values.email}
        error={errors.email}
        onChange={handleChange("email")}
        onBlur={handleBlur("email")}
        inputRef={refs.email}
      />

      <FormField
        id="phone"
        label="Phone number"
        type="tel"
        optional
        autoComplete="tel"
        inputMode="tel"
        helperText="Include country code if outside the US, e.g. +1 (555) 123-4567."
        value={values.phone}
        error={errors.phone}
        onChange={handleChange("phone")}
        onBlur={handleBlur("phone")}
        inputRef={refs.phone}
      />

      <button type="submit" className="submit-btn">Send message</button>

      <p className="form-status" role="status" aria-live="polite">{status}</p>
    </form>
  );
}

