+const { useState, useRef } = React;
+
+const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+const PHONE_RE = /^[0-9]{10}$|^\+?[0-9\s().-]{7,}$/;
+
+function FormField({ id, label, type, required, optional, autoComplete, helperText, value, error, inputMode, onChange, onBlur, inputRef }) {
+  const helperId = helperText ? `${id}-help` : null;
+  const errorId = `${id}-error`;
+  const describedBy = [helperId, error ? errorId : null].filter(Boolean).join(" ") || undefined;
+
+  return (
+    <div className="form-field">
+      <label htmlFor={id}>
+        {label}
+        {required && <span className="required-mark" aria-hidden="true">*</span>}
+        {optional && <span className="optional-tag">(optional)</span>}
+      </label>
+      <input
+        ref={inputRef}
+        id={id}
+        name={id}
+        type={type}
+        inputMode={inputMode}
+        value={value}
+        required={required || undefined}
+        autoComplete={autoComplete}
+        aria-describedby={describedBy}
+        aria-invalid={error ? "true" : undefined}
+        onChange={onChange}
+        onBlur={onBlur}
+      />
+      {helperText && (
+        <p id={helperId} className="helper-text">{helperText}</p>
+      )}
+      <p id={errorId} className="error-text" role="alert">
+        {error ? `Error: ${error}` : ""}
+      </p>
+    </div>
+  );
+}
+
+function validate(values) {
+  const errors = {};
+  if (!values.fullName.trim()) {
+    errors.fullName = "Enter your full name.";
+  }
+  if (!values.email.trim()) {
+    errors.email = "Enter your email address.";
+  } else if (!EMAIL_RE.test(values.email.trim())) {
+    errors.email = "Enter a valid email like name@example.com.";
+  }
+  if (values.phone.trim() && !PHONE_RE.test(values.phone.trim())) {
+    errors.phone = "Enter a valid phone number, e.g. (555) 123-4567.";
+  }
+  return errors;
+}
+
+function ContactForm() {
+  const [values, setValues] = useState({ fullName: "", email: "", phone: "" });
+  const [errors, setErrors] = useState({});
+  const [touched, setTouched] = useState({});
+  const [status, setStatus] = useState("");
+
+  const refs = {
+    fullName: useRef(null),
+    email: useRef(null),
+    phone: useRef(null),
+  };
+
+  const handleChange = (field) => (e) => {
+    const next = { ...values, [field]: e.target.value };
+    setValues(next);
+    if (touched[field] || errors[field]) {
+      setErrors(validate(next));
+    }
+  };
+
+  const handleBlur = (field) => () => {
+    setTouched((t) => ({ ...t, [field]: true }));
+    setErrors(validate(values));
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    const newErrors = validate(values);
+    setErrors(newErrors);
+    setTouched({ fullName: true, email: true, phone: true });
+
+    const order = ["fullName", "email", "phone"];
+    const firstInvalid = order.find((f) => newErrors[f]);
+    if (firstInvalid) {
+      setStatus("");
+      refs[firstInvalid].current?.focus();
+      return;
+    }
+    setStatus("Thanks! Your message has been received. Our support team will reply soon.");
+    setValues({ fullName: "", email: "", phone: "" });
+    setTouched({});
+  };
+
+  return (
+    <form className="card" noValidate onSubmit={handleSubmit} aria-labelledby="form-title">
+      <p className="required-legend">
+        Fields marked with <span className="required-mark" aria-hidden="true">*</span> are required.
+      </p>
+
+      <FormField
+        id="fullName"
+        label="Full name"
+        type="text"
+        required
+        autoComplete="name"
+        value={values.fullName}
+        error={errors.fullName}
+        onChange={handleChange("fullName")}
+        onBlur={handleBlur("fullName")}
+        inputRef={refs.fullName}
+      />
+
+      <FormField
+        id="email"
+        label="Email address"
+        type="email"
+        required
+        autoComplete="email"
+        inputMode="email"
+        value={values.email}
+        error={errors.email}
+        onChange={handleChange("email")}
+        onBlur={handleBlur("email")}
+        inputRef={refs.email}
+      />
+
+      <FormField
+        id="phone"
+        label="Phone number"
+        type="tel"
+        optional
+        autoComplete="tel"
+        inputMode="tel"
+        helperText="Include country code if outside the US, e.g. +1 (555) 123-4567."
+        value={values.phone}
+        error={errors.phone}
+        onChange={handleChange("phone")}
+        onBlur={handleBlur("phone")}
+        inputRef={refs.phone}
+      />
+
+      <button type="submit" className="submit-btn">Send message</button>
+
+      <p className="form-status" role="status" aria-live="polite">{status}</p>
+    </form>
+  );
+}
+
+function App() {
+  return (
+    <div className="page">
+      <header className="page-header">
+        <h1 id="form-title">Contact support</h1>
+        <p className="subtitle">Send us a note and we'll get back to you as soon as we can.</p>
+      </header>
+      <main id="main">
+        <ContactForm />
+      </main>
+    </div>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<App />);
+
')

